/**
 * clamp - Constrains a number to a min/max range.
 *
 * @param value - The number to clamp
 * @param min - Minimum allowed value
 * @param max - Maximum allowed value
 * @returns The clamped value
 *
 * @example
 * clamp(10, 0, 5)  // => 5
 * clamp(-5, 0, 10) // => 0
 * clamp(7, 0, 10)  // => 7
 */
export function clamp(value: number, min: number, max: number): number {
  // Handle NaN by preserving it through the comparisons
  if (Number.isNaN(value) || Number.isNaN(min) || Number.isNaN(max)) {
    return Number.NaN;
  }

  if (value < min) {
    return min;
  }

  if (value > max) {
    return max;
  }

  return value;
}

export default clamp;

/**
 * @file formatCurrency - Locale-aware currency formatting utility
 * @module @dsai-io/react/utils/number
 *
 * Enterprise-grade currency formatting with:
 * - Intl.NumberFormat with SSR-safe fallbacks
 * - ISO 4217 currency code support
 * - Currency display modes (symbol, code, name, narrow)
 * - Locale-specific formatting
 * - Formatter caching for performance
 * - Comprehensive input validation
 */

import type { CurrencyFormatterOptions } from '../types/shared';

/**
 * Cache for Intl.NumberFormat instances to avoid recreating formatters
 * Key: serialized locale + currency + options
 * Value: Intl.NumberFormat instance
 * Max size: 100 formatters (LRU eviction)
 */
const formattersCache = new Map<string, Intl.NumberFormat>();
const MAX_CACHE_SIZE = 100;

/**
 * Common currency symbols for fallback formatting
 */
const CURRENCY_SYMBOLS: Record<string, string> = {
  USD: '$',
  EUR: '€',
  GBP: '£',
  JPY: '¥',
  CNY: '¥',
  INR: '₹',
  CAD: 'CA$',
  AUD: 'A$',
  CHF: 'CHF',
  SEK: 'kr',
  NZD: 'NZ$',
  KRW: '₩',
  SGD: 'S$',
  HKD: 'HK$',
  NOK: 'kr',
  MXN: 'MX$',
  BRL: 'R$',
  RUB: '₽',
  ZAR: 'R',
  TRY: '₺',
};

/**
 * Generate a stable cache key from locale, currency, and options
 */
function getCacheKey(
  locale: string,
  currency: string,
  options?: Omit<Intl.NumberFormatOptions, 'style' | 'currency'>
): string {
  if (!options || Object.keys(options).length === 0) {
    return `${locale}|${currency}`;
  }

  // Build stable cache key from known safe options
  // Avoid dynamic JSON.stringify to prevent injection issues
  const parts: string[] = [];

  if (options.currencyDisplay !== undefined) {
    parts.push(`cd:${options.currencyDisplay}`);
  }
  if (options.currencySign !== undefined) {
    parts.push(`cs:${options.currencySign}`);
  }
  if (options.minimumFractionDigits !== undefined) {
    parts.push(`minfd:${options.minimumFractionDigits}`);
  }
  if (options.maximumFractionDigits !== undefined) {
    parts.push(`maxfd:${options.maximumFractionDigits}`);
  }
  if (options.useGrouping !== undefined) {
    parts.push(`ug:${options.useGrouping}`);
  }

  const optionsStr = parts.join('|');
  return `${locale}|${currency}|${optionsStr}`;
}

/**
 * Evict oldest entries from cache when it grows too large (LRU-style)
 */
function evictOldestEntries(): void {
  const entriesToRemove = Math.floor(MAX_CACHE_SIZE * 0.2); // Remove 20%
  const iterator = formattersCache.keys();

  for (let i = 0; i < entriesToRemove; i++) {
    const result = iterator.next();
    if (!result.done) {
      formattersCache.delete(result.value);
    }
  }
}

/**
 * Get or create a cached Intl.NumberFormat instance
 */
function getOrCreateFormatter(
  locale: string,
  currency: string,
  options?: Omit<Intl.NumberFormatOptions, 'style' | 'currency'>
): Intl.NumberFormat {
  const cacheKey = getCacheKey(locale, currency, options);
  let formatter = formattersCache.get(cacheKey);

  if (!formatter) {
    if (formattersCache.size >= MAX_CACHE_SIZE) {
      evictOldestEntries();
    }

    formatter = new Intl.NumberFormat(locale, {
      style: 'currency',
      currency,
      ...options,
    });
    formattersCache.set(cacheKey, formatter);
  }

  return formatter;
}

/**
 * Fallback currency formatter for environments without Intl support
 * Provides basic currency formatting using native methods and common symbols
 */
function fallbackFormat(
  value: number,
  currency: string,
  options?: Omit<Intl.NumberFormatOptions, 'style' | 'currency'>
): string {
  // Handle special values
  if (Number.isNaN(value)) {
    return 'NaN';
  }

  if (!Number.isFinite(value)) {
    return value > 0 ? 'Infinity' : '-Infinity';
  }

  // Get currency symbol (fallback to currency code)
  const symbol = CURRENCY_SYMBOLS[currency.toUpperCase()] ?? currency.toUpperCase();

  // Determine display mode
  const currencyDisplay = options?.currencyDisplay ?? 'symbol';
  const displayValue =
    currencyDisplay === 'code' || currencyDisplay === 'name' ? currency.toUpperCase() : symbol;

  // Format number with fraction digits (default to 2 for most currencies, 0 for JPY/KRW)
  const defaultFractionDigits = ['JPY', 'KRW'].includes(currency.toUpperCase()) ? 0 : 2;
  const fractionDigits =
    options?.minimumFractionDigits ?? options?.maximumFractionDigits ?? defaultFractionDigits;

  let formattedValue = Math.abs(value).toFixed(fractionDigits);

  // Add thousand separators
  if (options?.useGrouping !== false) {
    const parts = formattedValue.split('.');
    if (parts[0]) {
      // Safe regex: matches non-boundary followed by groups of exactly 3 digits
      const integerPart = parts[0];
      const reversed = integerPart.split('').reverse().join('');
      const grouped = reversed.replace(/(\d{3})(?=\d)/g, '$1,');
      parts[0] = grouped.split('').reverse().join('');
    }
    formattedValue = parts.join('.');
  }

  // Handle sign
  const sign = value < 0 ? '-' : '';

  // Format with currency (symbol before for most locales, after for some)
  // This is a simplified approach - Intl does this properly per locale
  if (currencyDisplay === 'name') {
    return `${sign}${formattedValue} ${displayValue}`;
  }

  return `${sign}${displayValue}${formattedValue}`;
}

/**
 * Format a number as currency according to locale and formatting options
 *
 * @param value - Number to format as currency
 * @param options - Formatting options (currency code, locale, display mode, etc.)
 * @returns Formatted currency string
 *
 * @throws {TypeError} If value is not a valid number
 * @throws {RangeError} If currency code is invalid (when using Intl)
 *
 * @example
 * ```tsx
 * // Basic formatting (USD default)
 * formatCurrency(1234.56); // "$1,234.56"
 * formatCurrency(1234.56, { currency: 'EUR' }); // "€1,234.56"
 *
 * // Different locales
 * formatCurrency(1234.56, { locale: 'de-DE', currency: 'EUR' }); // "1.234,56 €"
 * formatCurrency(1234.56, { locale: 'ja-JP', currency: 'JPY' }); // "¥1,235"
 * formatCurrency(1234.56, { locale: 'fr-FR', currency: 'EUR' }); // "1 234,56 €"
 *
 * // Currency display modes
 * formatCurrency(1234.56, {
 *   currency: 'USD',
 *   currencyDisplay: 'symbol'
 * }); // "$1,234.56" (default)
 *
 * formatCurrency(1234.56, {
 *   currency: 'USD',
 *   currencyDisplay: 'code'
 * }); // "USD 1,234.56"
 *
 * formatCurrency(1234.56, {
 *   currency: 'USD',
 *   currencyDisplay: 'name'
 * }); // "1,234.56 US dollars"
 *
 * formatCurrency(1234.56, {
 *   currency: 'USD',
 *   currencyDisplay: 'narrowSymbol'
 * }); // "$1,234.56"
 *
 * // Fraction digits control
 * formatCurrency(1234.567, {
 *   currency: 'USD',
 *   minimumFractionDigits: 2,
 *   maximumFractionDigits: 3
 * }); // "$1,234.567"
 *
 * // No grouping
 * formatCurrency(1234.56, {
 *   currency: 'USD',
 *   useGrouping: false
 * }); // "$1234.56"
 *
 * // Currencies with no decimals
 * formatCurrency(1234, { currency: 'JPY' }); // "¥1,234"
 * formatCurrency(1234, { currency: 'KRW' }); // "₩1,234"
 * ```
 */
export function formatCurrency(value: number, options: CurrencyFormatterOptions = {}): string {
  // Extract locale and currency from options
  const { locale = 'en-US', currency = 'USD', ...intlOptions } = options;

  // Validate input
  if (typeof value !== 'number') {
    throw new TypeError(`formatCurrency expects a number, received ${typeof value}`);
  }

  // SSR safety check - if Intl is not available, use fallback
  if (typeof Intl === 'undefined' || typeof Intl.NumberFormat === 'undefined') {
    return fallbackFormat(value, currency, intlOptions);
  }

  try {
    const formatter = getOrCreateFormatter(locale, currency, intlOptions);
    return formatter.format(value);
  } catch (error) {
    // Fallback if formatter fails (e.g., invalid currency code or options)
    if (process.env['NODE_ENV'] !== 'production') {
      console.warn('formatCurrency: Intl.NumberFormat failed, using fallback', error);
    }
    return fallbackFormat(value, currency, intlOptions);
  }
}

/**
 * Clear the formatter cache
 * Useful for testing or when you need to free memory
 */
formatCurrency.clearCache = (): void => {
  formattersCache.clear();
};

/**
 * Get the current size of the formatter cache
 * Useful for debugging and monitoring
 */
formatCurrency.getCacheSize = (): number => {
  return formattersCache.size;
};

/**
 * @file formatNumber - Locale-aware number formatting utility
 * @module @dsai-io/react/utils/number
 *
 * Enterprise-grade number formatting with:
 * - Intl.NumberFormat with SSR-safe fallbacks
 * - Compact notation (1K, 1.2M, 1.5B)
 * - Scientific and engineering notation
 * - Locale-specific grouping and decimal separators
 * - Formatter caching for performance
 * - Comprehensive input validation
 */

import type { NumberFormatterOptions } from '../types/shared';

/**
 * Cache for Intl.NumberFormat instances to avoid recreating formatters
 * Key: serialized locale + options
 * Value: Intl.NumberFormat instance
 * Max size: 100 formatters (LRU eviction)
 */
const formattersCache = new Map<string, Intl.NumberFormat>();
const MAX_CACHE_SIZE = 100;

/**
 * Generate a stable cache key from locale and options
 */
function getCacheKey(locale: string, options?: Intl.NumberFormatOptions): string {
  if (!options) {
    return locale;
  }

  // Sort keys for consistent cache keys
  const sortedKeys = Object.keys(options).sort();
  const optionsStr = sortedKeys
    .map((key) => `${key}:${JSON.stringify(options[key as keyof Intl.NumberFormatOptions])}`)
    .join('|');

  return `${locale}|${optionsStr}`;
}

/**
 * Evict oldest entries from cache when it grows too large (LRU-style)
 */
function evictOldestEntries(): void {
  const entriesToRemove = Math.floor(MAX_CACHE_SIZE * 0.2); // Remove 20%
  const iterator = formattersCache.keys();

  for (let i = 0; i < entriesToRemove; i++) {
    const result = iterator.next();
    if (!result.done) {
      formattersCache.delete(result.value);
    }
  }
}

/**
 * Get or create a cached Intl.NumberFormat instance
 */
function getOrCreateFormatter(
  locale: string,
  options?: Intl.NumberFormatOptions
): Intl.NumberFormat {
  const cacheKey = getCacheKey(locale, options);
  let formatter = formattersCache.get(cacheKey);

  if (!formatter) {
    if (formattersCache.size >= MAX_CACHE_SIZE) {
      evictOldestEntries();
    }

    formatter = new Intl.NumberFormat(locale, options);
    formattersCache.set(cacheKey, formatter);
  }

  return formatter;
}

/**
 * Fallback number formatter for environments without Intl support
 * Provides basic number formatting using native methods
 */
function fallbackFormat(value: number, options?: Intl.NumberFormatOptions): string {
  // Handle special values
  if (Number.isNaN(value)) {
    return 'NaN';
  }

  if (!Number.isFinite(value)) {
    return value > 0 ? 'Infinity' : '-Infinity';
  }

  // Handle scientific notation
  if (options?.notation === 'scientific' || options?.notation === 'engineering') {
    return value.toExponential(options?.maximumFractionDigits ?? 2);
  }

  // Handle compact notation (basic approximation)
  if (options?.notation === 'compact') {
    const absValue = Math.abs(value);
    const sign = value < 0 ? '-' : '';

    if (absValue >= 1e12) {
      return `${sign}${(absValue / 1e12).toFixed(1)}T`;
    }
    if (absValue >= 1e9) {
      return `${sign}${(absValue / 1e9).toFixed(1)}B`;
    }
    if (absValue >= 1e6) {
      return `${sign}${(absValue / 1e6).toFixed(1)}M`;
    }
    if (absValue >= 1e3) {
      return `${sign}${(absValue / 1e3).toFixed(1)}K`;
    }
  }

  // Basic number formatting with fraction digits
  const fractionDigits = options?.maximumFractionDigits ?? options?.minimumFractionDigits ?? 0;
  let result = value.toFixed(fractionDigits);

  // Add thousand separators (basic, assumes comma separators)
  if (options?.useGrouping !== false) {
    const parts = result.split('.');
    if (parts[0]) {
      // Safe regex: matches non-boundary followed by groups of exactly 3 digits
      const integerPart = parts[0];
      const reversed = integerPart.split('').reverse().join('');
      const grouped = reversed.replace(/(\d{3})(?=\d)/g, '$1,');
      parts[0] = grouped.split('').reverse().join('');
    }
    result = parts.join('.');
  }

  return result;
}

/**
 * Format a number according to locale and formatting options
 *
 * @param value - Number to format
 * @param options - Formatting options (locale, notation, fraction digits, etc.)
 * @returns Formatted number string
 *
 * @throws {TypeError} If value is not a valid number
 *
 * @example
 * ```tsx
 * // Basic formatting
 * formatNumber(1234.56); // "1,234.56" (en-US)
 * formatNumber(1234.56, { locale: 'de-DE' }); // "1.234,56"
 *
 * // Compact notation
 * formatNumber(1500, { notation: 'compact' }); // "1.5K"
 * formatNumber(2500000, { notation: 'compact' }); // "2.5M"
 * formatNumber(3000000000, { notation: 'compact' }); // "3B"
 *
 * // Compact with locale
 * formatNumber(1500, {
 *   locale: 'de-DE',
 *   notation: 'compact',
 *   compactDisplay: 'long'
 * }); // "1,5 Tausend"
 *
 * // Scientific notation
 * formatNumber(1234.56, { notation: 'scientific' }); // "1.235E3"
 *
 * // Fraction digits control
 * formatNumber(1.2345, {
 *   minimumFractionDigits: 2,
 *   maximumFractionDigits: 4
 * }); // "1.2345"
 *
 * // No grouping
 * formatNumber(1234567, { useGrouping: false }); // "1234567"
 *
 * // Percentage
 * formatNumber(0.1234, { style: 'percent' }); // "12%"
 *
 * // Unit formatting
 * formatNumber(100, {
 *   style: 'unit',
 *   unit: 'megabyte'
 * }); // "100 MB"
 * ```
 */
export function formatNumber(value: number, options: NumberFormatterOptions = {}): string {
  // Extract locale from options (default to en-US)
  const { locale = 'en-US', ...intlOptions } = options;

  // Validate input
  if (typeof value !== 'number') {
    throw new TypeError(`formatNumber expects a number, received ${typeof value}`);
  }

  // Normalize negative zero to plain zero for consistent output
  const normalizedValue = Object.is(value, -0) ? 0 : value;

  // SSR safety check - if Intl is not available, use fallback
  if (typeof Intl === 'undefined' || typeof Intl.NumberFormat === 'undefined') {
    return fallbackFormat(normalizedValue, intlOptions);
  }

  try {
    const formatter = getOrCreateFormatter(locale, intlOptions);
    return formatter.format(normalizedValue);
  } catch (error) {
    // Fallback if formatter fails (e.g., invalid options)
    if (process.env['NODE_ENV'] !== 'production') {
      console.warn('formatNumber: Intl.NumberFormat failed, using fallback', error);
    }
    return fallbackFormat(normalizedValue, intlOptions);
  }
}

/**
 * Clear the formatter cache
 * Useful for testing or when you need to free memory
 */
formatNumber.clearCache = (): void => {
  formattersCache.clear();
};

/**
 * Get the current size of the formatter cache
 * Useful for debugging and monitoring
 */
formatNumber.getCacheSize = (): number => {
  return formattersCache.size;
};

export { clamp } from './clamp';
export { formatCurrency } from './formatCurrency';
export { formatNumber } from './formatNumber';
